birthdays = {'Alice': 'Apr 1', 'Bob': 'Dec 12'}
typed = iter(['Alice', 'Eve', 'Dec 5', 'Eve', ''])
while (name := next(typed)) != '':
    if name in birthdays:
        print(name, 'has birthday', birthdays[name])
    else:
        birthdays[name] = next(typed)
        print('Learned', name, birthdays[name])

words = ['ant', 'ape', 'bee', 'bat', 'cat']
groups = {}
for w in words:
    groups.setdefault(w[0], []).append(w)
print(groups)
from collections import defaultdict
g2 = defaultdict(list)
for w in words:
    g2[w[0]].append(w)
print(g2 == groups)

board = {'a1': 'wR', 'e1': 'wK', 'e8': 'bK'}
files = 'abcdefgh'
for r in range(8, 0, -1):
    row = [board.get(f + str(r), '..') for f in files]
    print(r, ' '.join(row))

squares = {f + r for f in 'abcdefgh'
           for r in '12345678'}
board = {'e1': 'wK', 'e8': 'bK', 'z9': 'wQ'}
bad = [s for s in board if s not in squares]
kings = sorted(p for p in board.values() if p[1] == 'K')
print(bad, kings, kings == ['bK', 'wK'])

guests = {'Alice': {'apples': 5, 'pretzels': 12},
          'Bob': {'apples': 2, 'ham sandwiches': 3}}
def total(item):
    return sum(v.get(item, 0) for v in guests.values())
print(total('apples'), total('cups'))
print(guests['Alice']['pretzels'])

stuff = {'rope': 1, 'torch': 6, 'gold coin': 42}
total = 0
for k, v in stuff.items():
    print(str(v) + ' ' + k)
    total += v
print('Total number of items:', total)

